def check_bash(tool_input, root, cwd, depth=0):
    command = tool_input.get("command") or ""
    if not isinstance(command, str):
        deny(UNREADABLE)
    lowered = " ".join(command.lower().split())

    for pat in INSTALL_PATTERNS:
        if pat in lowered:
